  </tr>
  <tr data-mce-fragment="1">
  <td data-mce-fragment="1"><strong>種類</strong></td>
  <td data-mce-fragment="1">純米酒</td>
  </tr>
  <tr data-mce-fragment="1">
  <td data-mce-fragment="1"><strong>日本酒度</strong></td>
  <td data-mce-fragment="1">-1.5</td>
  </tr>
  <tr data-mce-fragment="1">
  <td data-mce-fragment="1"><strong>アルコール度数</strong></td>
  <td data-mce-fragment="1">17度以上18度未満</td>
  </tr>
  <tr data-mce-fragment="1">
  <td data-mce-fragment="1"><strong>精米歩合</strong></td>
  <td data-mce-fragment="1"><span data-mce-fragment="1">55%</span></td>
  </tr>
  <tr data-mce-fragment="1">
  <td data-mce-fragment="1"><strong>内容量</strong></td>
  <td data-mce-fragment="1"><span data-mce-fragment="1">720ml&nbsp;</span></td>
